def split_csv(line):
    fields = []
    i = 0
    n = len(line)
    if n == 0:
        return [""]
    while True:
        if i < n and line[i] == '"':
            # quoted field
            i += 1
            field_chars = []
            closed = False
            while i < n:
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i+1] == '"':
                        field_chars.append('"')
                        i += 2
                        continue
                    else:
                        i += 1
                        closed = True
                        break
                else:
                    field_chars.append(c)
                    i += 1
            if not closed:
                return None
            if i < n:
                if line[i] == ',':
                    fields.append(''.join(field_chars))
                    i += 1
                    if i == n:
                        fields.append('')
                        return fields
                    continue
                else:
                    return None
            else:
                fields.append(''.join(field_chars))
                return fields
        else:
            start = i
            while i < n and line[i] != ',' and line[i] != '"':
                i += 1
            if i < n and line[i] == '"':
                return None
            field = line[start:i]
            if i < n and line[i] == ',':
                fields.append(field)
                i += 1
                if i == n:
                    fields.append('')
                    return fields
                continue
            else:
                fields.append(field)
                return fields

